<script setup lang="ts">
import{ref}from 'vue';import{useRoute,useRouter}from 'vue-router';import{api}from '@/api/client';const route=useRoute();const router=useRouter();const email=ref(String(route.query.email??''));const token=ref(String(route.query.token??''));const password=ref('');const confirmation=ref('');const error=ref('');const busy=ref(false);async function submit(){if(!token.value||password.value.length<12||password.value!==confirmation.value){error.value='Enter the reset token and matching passwords of at least 12 characters.';return}busy.value=true;try{await api.post('/auth/reset-password',{email:email.value,token:token.value,password:password.value,password_confirmation:confirmation.value});router.push('/login')}catch(e:any){error.value=e.response?.data?.message??'Password could not be reset.'}finally{busy.value=false}}</script>
<template><main class="login-page"><section class="login-panel"><RouterLink class="brand" to="/login"><span class="brand-mark">C</span> Court Hub</RouterLink><p class="eyebrow">NEW PASSWORD</p><h1>Choose a new password.</h1><form @submit.prevent="submit"><label>Email<input v-model="email" type="email"/></label><label>Reset token<input v-model="token"/></label><label>New password<input v-model="password" type="password"/></label><label>Confirm password<input v-model="confirmation" type="password"/></label><p v-if="error" class="form-error">{{error}}</p><button class="primary-button" :disabled="busy">Reset password</button></form></section><section class="login-art"><div><h2>Secure your account.</h2></div></section></main></template>
